local function startFrame()
 if FREEZE_FRAME>0 then return math.min(#ends,math.max(1,math.floor(FREEZE_FRAME))) end return 1
end
local function frameAt(t)
 local phase=LOOP and t%total or math.min(t,total-0.001)
